mapper.select:

		/*selectMasterMdCmFinalOrderDateViewPopList*/
		SELECT  
             MAX(CM.COM_NAME_LOC) AS BUYER_NAME ,
             MAX(A.DESCRIPTION) AS DESCRIPTION, MAX(A.SPECIFICATION) AS SPECIFICATION, 
             MAX(A.ADD_DATE) AS ADD_DATE 
               FROM ICOMPODT A  , ICOMCMPY CM
              WHERE A.BYIT_COMORG_CODE        = #{st_buyer}
                AND A.CONTRACT_NO  = #{st_contract_no}  
                AND A.CONTRACT_SEQ = #{st_contract_seq} 
                AND A.STATUS      != 'D'  AND A.BUYER = CM.COM_CODE
                AND A.BUYER_ITEM_NO = #{st_buyer_item_no}
                AND A.ITEM_QTY  = NVL(A.GR_QTY,0)
              GROUP BY A.BUYER, CONTRACT_NO, CONTRACT_SEQ
